    // FIXME: Audit that the environment access only happens in single-threaded code.
    unsafe {
        std::env::set_var(
            "OP_HUMAN_PRINCIPAL_COZO_DB_PATH",
            _catalog.root().join("human-cozo"),
        )
    };
