    let environment = [
        "TCHED_ROUTER_RUNTIME_ENDPOINT",
        "TCHED_ROUTER_RUNTIME_AGENT",
        "TCHED_ROUTER_RUNTIME_TOKEN",
        "OP_GRANTS_PATH",
        "OP_HUMAN_PRINCIPAL_COZO_DB_PATH",
        "OP_LOCAL_HUMAN_WIREGUARD_PUBKEY",
        "OP_LOCAL_HUMAN_SESSION_ID",
        "OP_LOCAL_HUMAN_PRINCIPAL_ID",
