    unsafe { std::env::set_var("ZEROCLOW_ROUTER_RUNTIME_AGENT", "dashboard") };
    // FIXME: Audit that the environment access only happens in single-threaded code.
    unsafe { std::env::remove_var("ZEROCLOW_ROUTER_RUNTIME_TOKEN") };
    RuntimeFixture { task, environment }
}

fn write_schema(dir: &std::path::Path, version: &str, description: &str) {
    let schema = op_state_store::PluginSchema::builder("zeroclow_router")
        .version(version)
        .description(description)
        .build();
    let blob = op_blob::blobify_plugin_schema("zeroclow_router", schema);
    op_blob::catalog::BlobStore::open(dir)
